CREATE TABLE security_credential_access_evidence(evidence_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),admission_id TEXT NOT NULL,admission_digest TEXT NOT NULL,permit_digest TEXT NOT NULL,runtime_binding_id TEXT NOT NULL,runtime_binding_digest TEXT NOT NULL,provider TEXT NOT NULL,provider_account_id TEXT NOT NULL,provider_deployment_id TEXT NOT NULL,adapter_identity TEXT NOT NULL,credential_reference TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('NOT_APPLICABLE','RESOLUTION_SUCCEEDED','RESOLUTION_FAILED','RESOLUTION_DENIED')),attempted_at TEXT NOT NULL,completed_at TEXT NOT NULL,failure_code TEXT,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL);
CREATE TABLE security_provider_runtime_attempts(attempt_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),request_id TEXT NOT NULL,sequence INTEGER NOT NULL,predecessor_attempt_id TEXT,runtime_binding_id TEXT,runtime_binding_digest TEXT,admission_id TEXT,admission_digest TEXT,oks_consumption_id TEXT,credential_access_evidence_id TEXT REFERENCES security_credential_access_evidence(evidence_id),provider TEXT NOT NULL,provider_account_id TEXT,provider_deployment_id TEXT,adapter_identity TEXT,model TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('GOVERNANCE_DENIED','CONFIGURATION_FAILED','CREDENTIAL_RESOLUTION_FAILED','TRANSPORT_FAILED','TRANSPORT_SUCCEEDED','CREDENTIAL_NOT_APPLICABLE')),failure_class TEXT,failure_code TEXT,transport_evidence_id TEXT,started_at TEXT NOT NULL,completed_at TEXT NOT NULL,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL,UNIQUE(request_id,sequence));
CREATE TABLE security_provider_runtime_fallback_lineage(lineage_id TEXT PRIMARY KEY,predecessor_attempt_id TEXT NOT NULL UNIQUE REFERENCES security_provider_runtime_attempts(attempt_id),successor_attempt_id TEXT NOT NULL UNIQUE REFERENCES security_provider_runtime_attempts(attempt_id),reason TEXT NOT NULL CHECK(reason='TECHNICAL_FAILURE'),linked_at TEXT NOT NULL,correlation_id TEXT NOT NULL,CHECK(predecessor_attempt_id<>successor_attempt_id));
CREATE TABLE security_runtime_evidence_audit_events(event_id TEXT PRIMARY KEY,event_kind TEXT NOT NULL,subject_id TEXT NOT NULL,outcome TEXT NOT NULL,failure_code TEXT,correlation_id TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE TRIGGER security_credential_evidence_immutable BEFORE UPDATE ON security_credential_access_evidence BEGIN SELECT RAISE(ABORT,'SECURITY_CREDENTIAL_EVIDENCE_IMMUTABLE');END;
CREATE TRIGGER security_credential_evidence_no_delete BEFORE DELETE ON security_credential_access_evidence BEGIN SELECT RAISE(ABORT,'SECURITY_CREDENTIAL_EVIDENCE_IMMUTABLE');END;
CREATE TRIGGER security_attempt_evidence_immutable BEFORE UPDATE ON security_provider_runtime_attempts BEGIN SELECT RAISE(ABORT,'SECURITY_ATTEMPT_EVIDENCE_IMMUTABLE');END;
CREATE TRIGGER security_attempt_evidence_no_delete BEFORE DELETE ON security_provider_runtime_attempts BEGIN SELECT RAISE(ABORT,'SECURITY_ATTEMPT_EVIDENCE_IMMUTABLE');END;
CREATE TRIGGER security_fallback_lineage_immutable BEFORE UPDATE ON security_provider_runtime_fallback_lineage BEGIN SELECT RAISE(ABORT,'SECURITY_FALLBACK_LINEAGE_IMMUTABLE');END;
CREATE TRIGGER security_fallback_lineage_no_delete BEFORE DELETE ON security_provider_runtime_fallback_lineage BEGIN SELECT RAISE(ABORT,'SECURITY_FALLBACK_LINEAGE_IMMUTABLE');END;
CREATE TRIGGER security_runtime_audit_immutable BEFORE UPDATE ON security_runtime_evidence_audit_events BEGIN SELECT RAISE(ABORT,'SECURITY_RUNTIME_AUDIT_IMMUTABLE');END;
CREATE TRIGGER security_runtime_audit_no_delete BEFORE DELETE ON security_runtime_evidence_audit_events BEGIN SELECT RAISE(ABORT,'SECURITY_RUNTIME_AUDIT_IMMUTABLE');END;
